import json
CFG = json.loads("{\"preset\": \"serve\", \"stop_min\": 600, \"resume_from\": [], \"prep\": [\"cache_validation\", \"cache_private\", \"cache_train\", \"types\"], \"parts\": \"weights,cube,types\", \"kernel\": \"tfb-kg-dwadapt-serve\", \"code_sha\": \"adaef924faff987a\", \"code_files\": 53, \"dataset\": \"aminmohamed333345/tfb-dwadapt-base-weights\", \"venv\": true}")
BLOB = ""
# L_dwadapt (DW-ADAPT, exp/L_dwadapt/LINE.md): Kaggle script runner. Generated kernel = "CFG = ...", "BLOB = ..." (base64 tar.gz of repo
# code + exp/L_dwadapt/dw_ref.json (digests only) + two I-Q-RAW window key lists; no data, no weights, no predictions, no credentials)
# + this file (exp/L_dwadapt/dw_make.py). Stdlib only. Same structure as exp/L_fvinel/fvi_kernel.py.
# Steps: venv with the laptop pins -> code to /tmp/tfb (TFB_ROOT) -> release linked -> base weights linked from the private weights-only
# dataset CFG["dataset"] -> resume copy (kernel_sources) -> prep (caches from the release, official types, TM-R select, c_bb_raw build)
# -> digests == laptop (dw_ref.py check; exit on mismatch) -> chk: k = 0 official sample with --ftcheck | inst/serve: jobs.json, one
# worker per GPU (dw_step.py worker), time guard CFG["stop_min"].
# Outputs: /kaggle/working/dw_pull.tar (artifacts/claude_ref/l_dwadapt/{tmr,off,official,parity}, jobs.json, logs), dw_summary.json,
# kg_log.jsonl.
import base64, glob, io, json, os, shutil, subprocess, sys, tarfile, threading, time
from pathlib import Path

T0 = time.time()
W = Path("/kaggle/working"); ROOT = Path("/tmp/tfb"); VENV = Path("/tmp/venv"); PY = str(VENV / "bin/python")
TEST = os.environ.get("KG_TEST_DIR")   # laptop dry run: scratch dirs, current python (KG_REL, KG_CACHE, KG_WEIGHTS)
if TEST:
    W = Path(TEST) / "working"; ROOT = Path(TEST) / "tfb"; PY = sys.executable
W.mkdir(parents=True, exist_ok=True); (W / "logs").mkdir(exist_ok=True)
A = "artifacts/claude_ref/l_dwadapt"
LOCK = threading.Lock()
elapsed = lambda: (time.time() - T0) / 60


def log(**k):
    k = dict(utc=time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime()), min=round(elapsed(), 2), **k)
    line = json.dumps(k)
    with LOCK:
        print("KG " + line, flush=True)
        with open(W / "kg_log.jsonl", "a") as f:
            f.write(line + "\n")


def sh(cmd, name, env=None, check=True, logname=None, quiet=False):
    t = time.time()
    with open(W / "logs" / f"{logname or name}.log", "a") as lf:
        p = subprocess.Popen(cmd, shell=isinstance(cmd, str), stdout=subprocess.PIPE, stderr=subprocess.STDOUT, text=True,
                             env=env, cwd=str(ROOT) if ROOT.exists() else None, bufsize=1)
        tail = []
        for line in p.stdout:
            tail = (tail + [line.rstrip()])[-15:]; lf.write(line); lf.flush()
            if not quiet or any(s in line for s in ("DONE", "Error", "DW_", "Traceback", "FAIL")):
                with LOCK:
                    print(f"[{name}] " + line, end="", flush=True)
        rc = p.wait()
    log(step=name, rc=rc, minutes=round((time.time() - t) / 60, 2))
    if check and rc != 0:
        raise RuntimeError(f"{name} failed rc={rc}: " + " | ".join(tail[-5:]))
    return rc


def link(dst, src):
    dst.parent.mkdir(parents=True, exist_ok=True)
    if dst.exists() or dst.is_symlink():
        return
    if TEST:
        shutil.copyfile(src, dst)
    else:
        dst.symlink_to(src)


def setup():
    ROOT.mkdir(parents=True, exist_ok=True)
    tarfile.open(fileobj=io.BytesIO(base64.b64decode(BLOB)), mode="r:gz").extractall(ROOT)
    (ROOT / "PLAN.md").write_text("Kaggle notebook copy of the TrafficFlowBench code (no plan here).\n")
    log(step="code", files=sum(1 for _ in ROOT.rglob("*.py")), code_sha=CFG.get("code_sha"))
    if not TEST and CFG.get("venv", True):
        sh(f"{sys.executable} -m pip install -q uv", "venv")
        uv = f"{sys.executable} -m uv"
        sh(f"{uv} venv {VENV} --python 3.12", "venv")
        sh(f"{uv} pip install --python {PY} -q torch==2.7.1+cu118 --index-url https://download.pytorch.org/whl/cu118 "
           f"--extra-index-url https://pypi.org/simple --index-strategy unsafe-best-match", "venv")
        sh(f"{uv} pip install --python {PY} -q numpy==2.4.4 pandas==3.0.2 pyarrow==23.0.1 psutil", "venv")
    rel = Path(os.environ["KG_REL"]) if TEST else None
    for pat in ("/kaggle/input/*/kaggle_public", "/kaggle/input/*/*/kaggle_public", "/kaggle/input/*/*/*/kaggle_public"):
        hits = sorted(glob.glob(pat))
        if hits and rel is None:
            rel = Path(hits[0])
    assert rel is not None and rel.is_dir(), "competition data not attached"
    dst = ROOT / "data/raw/kaggle_public"; dst.parent.mkdir(parents=True, exist_ok=True)
    if not dst.exists():
        if TEST:
            subprocess.run(["cmd", "/c", "mklink", "/J", str(dst), str(rel)], check=True, stdout=subprocess.DEVNULL)
        else:
            dst.symlink_to(rel)
    if TEST and os.environ.get("KG_CACHE"):
        subprocess.run(["cmd", "/c", "mklink", "/J", str(ROOT / "artifacts/cache"), os.environ["KG_CACHE"]], check=True, stdout=subprocess.DEVNULL)
    (ROOT / "artifacts/cache").mkdir(parents=True, exist_ok=True); (ROOT / "artifacts/claude_ref/ong2").mkdir(parents=True, exist_ok=True)
    # base weights: dataset file a__b__c -> artifacts/claude_ref/a/b/c
    if TEST:
        wd = Path(os.environ["KG_WEIGHTS"])
    else:
        hits = sorted(set(Path(p).parent for p in glob.glob("/kaggle/input/**/l_dose__a2__warm__heads.pt", recursive=True)))
        assert len(hits) == 1, f"weights dataset {CFG.get('dataset')} not found exactly once: {hits}"
        wd = hits[0]
    n = 0
    for f in sorted(wd.iterdir()):
        if "__" in f.name:
            link(ROOT / "artifacts/claude_ref" / f.name.replace("__", "/"), f); n += 1
    log(step="data_links", release=str(rel), weights=str(wd), files=n)


def env(threads=2, gpu=None):
    e = dict(os.environ, TFB_ROOT=str(ROOT), PYTHONIOENCODING="utf-8", PYTHONUNBUFFERED="1", PYTHONPATH=str(ROOT / "src"),
             OMP_NUM_THREADS=str(threads), MKL_NUM_THREADS=str(threads), DW_T0=str(T0), DW_STOP_MIN=str(CFG["stop_min"]))
    if gpu is not None:
        e["CUDA_VISIBLE_DEVICES"] = "" if TEST else str(gpu)
    return e


def n_gpu():
    if TEST:
        return 1
    try:
        out = subprocess.run("nvidia-smi --query-gpu=name --format=csv,noheader", shell=True, capture_output=True, text=True).stdout
        return max(1, len([l for l in out.splitlines() if l.strip()]))
    except Exception:
        return 1


def cache(split):
    code = ("import sys, json, importlib.util; sys.path.insert(0, 'docs/reference_code'); import tfb.data as D\n"
            "from pathlib import Path\nfrom qcnn_train import PANELS\nimport os\n"
            "def guard(root, destination, expected_bytes=0):\n"
            "    spec = importlib.util.spec_from_file_location('tfb_diskguard', Path(root) / 'tools' / 'diskguard.py')\n"
            "    m = importlib.util.module_from_spec(spec); spec.loader.exec_module(m)\n"
            "    return m.check_free_space(destination, expected_bytes=expected_bytes, reserve_gb=2.0)\n"
            "D.guard = guard\n"
            "for pn in PANELS:\n"
            f"    meta = D.build_cache(pn, {split!r}, root=Path(os.environ['TFB_ROOT']))\n"
            "    print(json.dumps({k: meta.get(k) for k in ('panel', 'split', 'runtime_seconds')}), flush=True)\n")
    sh([PY, "-c", code], f"cache_{split}", env(4))


PREP = {"cache_validation": lambda: cache("validation"), "cache_private": lambda: cache("private"), "cache_train": lambda: cache("train"),
        "types": lambda: sh([PY, "docs/reference_code/ong2_official_types.py"], "types", env(4)),
        "tmr_select": lambda: sh([PY, "exp/G_inst/g_tmr_export.py", "select"], "tmr_select", env(4)),
        "raw_build": lambda: sh([PY, "docs/reference_code/c_bb_raw.py", "build"], "raw_build", env(4))}


def resume():
    n = 0
    if CFG.get("resume_from"):
        for tp in sorted(glob.glob(os.environ.get("KG_RESUME_GLOB", "/kaggle/input/**/dw_pull.tar"), recursive=True)):
            with tarfile.open(tp) as tf:
                for m in tf.getmembers():
                    if not m.isfile() or not m.name.startswith(A + "/") or ".." in m.name:
                        continue
                    if not any(m.name.startswith(f"{A}/{d}/") for d in ("tmr", "off", "official")):
                        continue
                    dst = ROOT / m.name
                    if dst.exists():
                        continue
                    dst.parent.mkdir(parents=True, exist_ok=True)
                    with tf.extractfile(m) as f, open(dst, "wb") as g:
                        shutil.copyfileobj(f, g)
                    n += 1
        log(step="resume", files_copied=n, sources=CFG["resume_from"])


def pack():
    files = [p for p in (ROOT / A).rglob("*") if p.is_file() and not p.name.endswith(".tmp.npz")]
    files += [p for p in (ROOT / "logs_dw").glob("*.log")] if (ROOT / "logs_dw").exists() else []
    tmp = W / "dw_pull.tar.tmp"
    with tarfile.open(tmp, "w") as tf:
        for p in sorted(files):
            tf.add(p, arcname=str(p.relative_to(ROOT)).replace("\\", "/"))
        for p in sorted((W / "logs").glob("*.log")):
            tf.add(p, arcname="kg_logs/" + p.name)
    os.replace(tmp, W / "dw_pull.tar")
    log(step="pack", files=len(files), mb=round((W / "dw_pull.tar").stat().st_size / 2**20, 1))


if __name__ == "__main__":
    log(step="start", kernel=CFG.get("kernel"), preset=CFG["preset"], prep=CFG["prep"], stop_min=CFG["stop_min"])
    if not TEST:
        subprocess.run("nvidia-smi --query-gpu=name,memory.total,driver_version --format=csv,noheader; nproc; free -g | head -2; "
                       "df -h /kaggle/working /tmp | tail -2", shell=True)
    err = None; workers = []; OUTJ = ROOT / A / "jobs"
    try:
        setup(); resume()
        sh([PY, "exp/L_dwadapt/dw_ref.py", "check", "--parts=weights"], "check_weights", env(2))
        for s in CFG["prep"]:
            if TEST and s.startswith("cache_") and os.environ.get("KG_CACHE"):
                continue
            PREP[s]()
        sh([PY, "exp/L_dwadapt/dw_ref.py", "check", f"--parts={CFG['parts']}"], "check", env(4))
        if CFG.get("check_only"):
            sh([PY, "exp/L_dwadapt/dw_step.py", "sample"], "sample", env(2))
            raise SystemExit(0)
        sh([PY, "exp/L_dwadapt/dw_step.py", "plan", CFG["preset"], str(OUTJ)], "plan", env(1))
        G = n_gpu(); log(step="workers", n=G)
        ths = [threading.Thread(target=lambda g=g: workers.append(sh([PY, "exp/L_dwadapt/dw_step.py", "worker", str(OUTJ), str(g), str(G)], f"worker{g}",
                                                                     env(2, g), check=False, logname=f"gpu{g}", quiet=True))) for g in range(G)]
        for th in ths:
            th.start()
        for th in ths:
            th.join()
    except SystemExit:
        log(step="check_only_done")
    except Exception as ex:
        err = str(ex)[:500]; log(step="fatal", error=err)
    js = json.loads((OUTJ / "jobs.json").read_text()) if (OUTJ / "jobs.json").exists() else []
    done = [j["name"] for j in js if (ROOT / j["out"]).exists()]
    fails = []
    for f in (W / "logs").glob("gpu*.log"):
        fails += [l.strip()[:300] for l in f.read_text(errors="replace").splitlines() if l.startswith("DW_JOB_FAILED")]
    summ = dict(kernel=CFG.get("kernel"), code_sha=CFG.get("code_sha"), preset=CFG["preset"], minutes_total=round(elapsed(), 2), error=err,
                jobs=len(js), done=len(done), left=len(js) - len(done), failed=fails, worker_rc=workers)
    (W / "dw_summary.json").write_text(json.dumps(summ, indent=1))
    try:
        pack()
    except Exception as ex:
        err = err or f"pack: {str(ex)[:300]}"; log(step="pack_failed", error=str(ex)[:300])
    log(step="end", **{k: summ[k] for k in ("minutes_total", "jobs", "done", "left")}, failed=len(fails))
    if err or any(rc != 0 for rc in workers):
        sys.exit(1)
